import React from 'react'
import { ScrollView, StyleSheet, Text, View } from 'react-native'
import { useNavigation } from '@react-navigation/native'
import { COLORS, RADIUS, SPACING } from '../theme'
import {
  Avatar,
  Card,
  MenuRow,
  PrimaryButton,
  RowDivider,
  Screen,
  ScreenHeader,
  SectionTitle,
  confirmAction,
} from '../components/CollectionUI'
import { useAuth } from '../context/AuthContext'
// Read straight from app.json (tsconfig has resolveJsonModule) instead of
// expo-constants, which is only a transitive dependency of `expo` here.
import appConfig from '../../app.json'

/**
 * Settings hub: profile card + grouped rows + logout, following the
 * Collectionapp settings/index.jsx layout (its rows use the same
 * icon-tile / title / subtitle / chevron rhythm).
 */
export default function SettingsScreen(){
  const navigation = useNavigation()
  const { user, logout } = useAuth()
  const isAdmin = user?.role !== 'User'
  const version = appConfig.expo?.version || '1.0.0'
  const appName = appConfig.expo?.name || 'Farmer App'

  const onLogout = ()=>{
    confirmAction('Logout', 'Are you sure you want to log out?', ()=>{
      logout()
      // AppRoutes swaps MainStack for AuthStack as soon as the session clears,
      // so the whole stack (including this screen) unmounts and Login shows.
    })
  }

  return (
    <Screen>
      <ScreenHeader title="Settings" subtitle={user?.username || 'Guest'} />
      <ScrollView contentContainerStyle={styles.body} showsVerticalScrollIndicator={false}>
        <Card style={styles.profile}>
          <Avatar name={user?.username || 'Guest'} size={56} />
          <View style={styles.profileMid}>
            <Text style={styles.profileName}>{user?.username || 'Guest'}</Text>
            <Text style={styles.profileMeta}>
              {user?.id ? `Account #${user.id} · ` : ''}
              {isAdmin ? 'Administrator' : 'Standard user'}
            </Text>
          </View>
          <View style={styles.rolePill}>
            <Text style={styles.rolePillText}>{isAdmin ? 'Admin' : 'User'}</Text>
          </View>
        </Card>

        <View style={styles.group}>
          <SectionTitle>Account</SectionTitle>
          <Card style={styles.groupCard}>
            <MenuRow
              icon="lock-closed"
              title="Change Password"
              subtitle="Update the password for this account"
              onPress={()=> (navigation as any).navigate('ChangePassword')}
            />
            <RowDivider />
            <MenuRow
              icon="grid"
              title="All Menu"
              subtitle="Jump to any screen"
              onPress={()=> (navigation as any).navigate('Menu')}
            />
          </Card>
        </View>

        {isAdmin ? (
          <View style={styles.group}>
            <SectionTitle>Administration</SectionTitle>
            <Card style={styles.groupCard}>
              <MenuRow
                icon="people"
                title="User Management"
                subtitle="Add, edit and remove accounts"
                onPress={()=> (navigation as any).navigate('Users')}
              />
            </Card>
          </View>
        ) : null}

        <View style={styles.group}>
          <SectionTitle>Security</SectionTitle>
          <Card style={styles.groupCard}>
            <MenuRow icon="log-out" title="Logout" subtitle="Sign out of this device" danger onPress={onLogout} />
          </Card>
        </View>

        <View style={styles.group}>
          <SectionTitle>About</SectionTitle>
          <Card style={styles.about}>
            <AboutRow label="App" value={appName} />
            <AboutRow label="Version" value={version} />
            <AboutRow label="Storage" value="On-device (offline first)" />
          </Card>
        </View>

        <PrimaryButton label="Logout" variant="danger" onPress={onLogout} />
      </ScrollView>
    </Screen>
  )
}

function AboutRow({ label, value }: { label: string; value: string }){
  return (
    <View style={styles.aboutRow}>
      <Text style={styles.aboutLabel}>{label}</Text>
      <Text style={styles.aboutValue}>{value}</Text>
    </View>
  )
}

const styles = StyleSheet.create({
  body: { padding: SPACING.md, gap: SPACING.lg },
  profile: { flexDirection: 'row', alignItems: 'center', gap: 12 },
  profileMid: { flex: 1 },
  profileName: { fontSize: 17, fontWeight: '800', color: COLORS.textPrimary },
  profileMeta: { fontSize: 12, color: COLORS.textSecondary, marginTop: 2 },
  rolePill: {
    backgroundColor: COLORS.primaryBg,
    paddingHorizontal: 10,
    paddingVertical: 5,
    borderRadius: RADIUS.full,
  },
  rolePillText: { fontSize: 11, fontWeight: '800', color: COLORS.primary },
  group: { gap: SPACING.sm },
  groupCard: { padding: 0, overflow: 'hidden' },
  about: { gap: 10 },
  aboutRow: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center' },
  aboutLabel: { fontSize: 13, color: COLORS.textSecondary },
  aboutValue: { fontSize: 13, fontWeight: '700', color: COLORS.textPrimary },
})